def cached(cache, key=hashkey, lock=None):
    @wraps(func)
    def wrapper(*args, **kwargs):
        key = key(*args, **kwargs)
        if lock:
            lock.acquire()
        try:
            result = cache[key]
        except KeyError:
            result = func(*args, **kwargs)
            cache[key] = result
        finally:
            if lock:
                lock.release()
        return result
    return wrapper

class MruCache(object):
    def __init__(self, maxsize=128, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = {}

    def __call__(self, func):
        def wrapper(*args, **kwds):
            key = args
            if self.typed:
                key += tuple(type(x) for x in args)
            key += tuple(sorted(kwds.items()))
            if key in self.cache:
                value = self.cache[key]
            else:
                value = func(*args, **kwds)
                self.cache[key] = value
            self.cache = collections.OrderedDict(
                (key, value),
                **self.cache)
            if len(self.cache) > self.maxsize:
                self.cache.popitem(last=False)
            return value

        return wrapper

# This method is a decorator that wraps a function with a memoizing callable that saves up to `maxsize` results based on a Least Recently Used (LRU) algorithm.
def lru_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        def wrapped_func(*args):
            if typed:
                key = (args, tuple(type(a) for a in args))
            else:
                key = args
            if key not in cache:
                cache[key] = func(*args)
            else:
                del cache[key]
                cache[key] = maxsize
    return wrapper

