def generate_default_observer_schema(app):
    # Map of custom resource definitions (CRDs) for this application's namespace
    crds = app.spec.get_custom_resource_definitions()
    # List of all Kubernetes resources present in the manifest defined by the application
    resources = app.spec.manifest.resources.values()

    # Loop over all resources in the manifest and create a default observer schema for each
    # that doesn't already have a custom schema defined by the user
    for resource in resources:
        # Skip resources that have a custom schema defined by the user
        if resource.schema:
            continue

        # Determine the corresponding CRD for this resource
        crd = None
        for crd_name in crds:
            if crd_name in resource.api_version:
                crd = crds[crd_name]
                break

        # Create a default observer schema for this resource based on its CRD metadata
        if crd:
            resource.schema = {
                'title': resource.metadata.name,
                'type': 'object',
                'properties': {
                    'spec': {
                        'type': 'object',
                        'properties': {
                            'hostname': {
                                'type': 'string'
                            },
                            'port': {
                                'type': 'integer'
                            }
                        }
                    }
                }
            }

            # Add any additional properties defined by the CRD
            for field in crd.spec.names.singular.split('.') + crd.spec.names.categories:
                path = resource.metadata.name + '.' + field
                if path not in resource.schema['properties']:
                    resource.schema['properties'][path] = {
                        'type': 'object'
                    }

def format(sql, params):
    new_sql = sql
    new_params = {}

    if isinstance(params, (dict, tuple)):
        param_names = set(param[0] for param in sql.parameters if param[1].kind == 'name')
        param_indexes = set(param[1].index for param in sql.parameters if param[1].kind == 'position')

        if param_names and param_indexes:
            raise ValueError('cannot support both named and posational parameters in the same SQL query')

        for key, value in params.items():
            if key in param_names:
                new_sql = new_sql.replace(f'{key}', f'%({key})s')
                new_params[key] = value
            elif key in param_indexes:
                new_sql = new_sql.replace(f'%s', f'%({key})s')
                new_params[key] = value
            else:
                raise ValueError(f'no parameter found with the name or index {key}')

    else:
        new_sql = sql
        new_params = params

    return new_sql, new_params

def formatmany(sql, many_params):
    # Convert the SQL query to use the out-style parameters instead of the in-style parameters
    params = []
    for p in many_params:
        # Create a dictionary to hold the out-style parameters
        out_params = {}
        # Iterate over the in-style parameters
        for k, v in p.items():
            # If the parameter is not a named parameter, add it to the list of out-style parameters
            if not isinstance(k, str):
                out_params[k] = v
            # If the parameter is a named parameter, add it to the dictionary of out-style parameters
            else:
                out_params[k] = v
        # Add the converted out-style parameters to the list
        params.append(out_params)
    return sql, params

