import os

def inject_config(self):
    config_path = os.getenv('CONFIG_PATH')
    if not config_path:
        os.environ['CONFIG_PATH'] = self.get_default_config_path()
        print(f'Environment variable CONFIG_PATH is not set, using {self.get_default_config_path()} as default.')
    else:
        print(f'Environment variable CONFIG_PATH is already set to {config_path}.')
